  'repeat.toast_saved': "Kaydedildi. Ekranlara uygulamak için yayımlayın.",
  'widget.web.interactive': "Etkileşimli (ziyaretçi kiosku)",
  'widget.web.interactive_hint': "Ziyaretçiler formlara dokunabilir, kaydırabilir ve doldurabilir. Birisi sayfayı kullanırken oynatma listesi duraklatılır ve sayfadan ayrıldıktan sonra sayfa sıfırlanır ve yaptığı her şey silinir. Yalnızca tam ekran. Android, Windows ve Raspberry Pi yerel oynatıcıları ve BrightSign'da tam destek; web, webOS ve Tizen ekranları, siteyi silemeyen veya diğer siteleri engelleyemeyen sınırlı bir sürüme sahip olur.",
