  'widget.web.home_button': "Ziyaretçi başlangıç sayfasından ayrıldığında Ana Sayfa düğmesini göster",
  'widget.web.idle_warning': "Sıfırlamadan önce “Hâlâ burada mısınız?” geri sayımı",
  'widget.web.idle_warning_off': "Kapalı (hemen sıfırla)",
  'widget.web.idle_warning_sec': "{n} saniye",
  'widget.web.idle_warning_hint': "Ziyaretçiye dokunup devam etmek için kısa bir süre tanır. Mağazalarda yararlıdır; bilgi sayfalarında kapatılabilir.",
  'widget.web.wipe_site_data': "Her ziyaretçiden sonra sitenin çerezlerini ve depolama alanını silin",
  'widget.web.wipe_site_data_hint': "Menü, fiyat listesi veya harita gibi korunacak veri içermeyen bilgi sayfalarında kapatabilirsiniz; çerez bildirimi tercihi ve seçilen dil korunur. Her ziyaretçi yine temiz bir sayfa, geçmiş ve form verileriyle başlar. Bir ekrandaki web sayfaları aynı depolamayı paylaşır; başka bir öğe verileri silerse bunlar da silinir. Windows ve Raspberry Pi oynatıcıları çerezleri korur, site depolamasını korumaz. BrightSign her zaman siler.",
  'widget.web.keep_consent': "Sitenin çerez onayı seçimini ziyaretçiler arasında tutun",
  'widget.web.keep_consent_hint': "Yalnızca izin verilen sitelerin onay çerezleri korunur. Oturum açma bilgileri, sepetler ve diğer veriler her ziyaretçiden sonra silinir. Tercihi çerez yerine localStorage içinde saklayan onay araçları tekrar sorar.",
  'widget.web.keep_cookie_names': "Saklanacak diğer çerez adları",
