  'nav.automation': "Otomasyon",
  'auto.intro': "Bırakın diğer sistemler ekranlarınızın gösterdiklerini değiştirsin: yangın paneli, Alertus, InformaCast, Zapier, Make veya n8n. Her kanca gizli bir web adresidir; bunu çağırmak bir uyarıyı tetikler, bir tetikleyiciyi harekete geçirir, bir tabloyu günceller veya ekranları bir oynatma listesine değiştirir.",
  'auto.new': "Yeni bağlantı",
