  'auto.hint.emergency': "Acil durum akışıyla aynı şekilde ekranlarda acil durum uyarısı gösterir. Aynı uyarı kimliği yeniden gönderildiğinde değişiklik olmaz. Temizleme isteği uyarıyı sonlandırır.",
  'auto.hint.mass_notification': "Toplu bildirim sistemleri için. Alertus, InformaCast ve benzeri sistemlerden CAP 1.2 XML veya JSON'u kabul eder. Uyarılar, gönderenin kendi uyarı kimliğine göre eşleştirilir; dolayısıyla bir tekrar veya yeniden deneme bir kez gösterilir ve temizleme işlemi bunu sonlandırır.",
  'auto.hint.trigger': "Atandığı ekranlarda tetikleyicilerinizden birini tetikler.",
  'auto.hint.data': "Aldığı satırları bir Tablo veri kaynağına yazar, böylece onu kullanan slaytlar ve menü panoları güncellenir.",
  'auto.hint.playlist': "Birkaç dakika boyunca ekranları bir oynatma listesine geçirir, sonra geri dönerler. Hiçbir zaman merkez ofisin oynatma listesi için geçerli değildir ve acil durum uyarısı yine de ilk sırada gelir.",
