  'auto.zapier_title': "Zapier, Make ve n8n",
  'auto.zapier_intro': "Zapier, burada bir şey olduğunda (bir ekran çevrimdışı olduğunda, bir uyarı verildiğinde, bir oynatma listesi yayımlandığında) bir Zap başlatabilir ve eylemleri uyarıları yükseltebilir, oynatma listelerini değiştirebilir, tetikleyicileri tetikleyebilir ve tabloları güncelleyebilir.",
