  'auto.mn_explain': "Toplu bildirim sisteminizi bu kancanın adresine yönlendirin. CAP, Alertus ve InformaCast için alanlar otomatik olarak bulunur; Göndereniniz başka adlar kullanıyorsa aşağıdan bir eşleme ayarlayın.",
