  'simple.help.g1.title': "Bir ekran bağlayın",
  'simple.help.g1.s1': "Kullanmak istediğiniz TV, tablet veya bilgisayarda oynatıcıyı açın: Android uygulamasını yükleyin veya bu sitenin /player sayfasını web tarayıcısında açın.",
  'simple.help.g1.s2': "Elinizde TV yok mu? Denemek için oynatıcıyı başka bir tarayıcı sekmesinde açın.",
  'simple.help.g1.s3': "Oynatıcı 6 haneli bir kod gösterir. Burada \"Ekran ekle\"yi seçin ve yazın.",
  'simple.help.g1.s4': "Ekrana “Vitrin” gibi kolay tanıyacağınız bir ad verin.",
  'simple.help.g2.title': "Ekrandaki içeriği değiştir",
  'simple.help.g2.s1': "“Ekrandaki içeriği değiştir” seçeneğini veya “Ekranlarınız” altından bir ekranı seçin.",
  'simple.help.g2.s2': "Yalnızca yeni şeyleri göstermek için \"Değiştir\"i, halihazırda oynatılanları tutmak için \"Ekle\"yi seçin.",
  'simple.help.g2.s3': "Fotoğraf veya video yükleyin, daha önce yüklediklerinizi seçin veya aynısını başka bir ekranda gösterin.",
  'simple.help.g2.s4': "Ekran birkaç saniye içinde güncellenir.",
  'simple.help.g3.title': "Fotoğraf ve video yükle",
  'simple.help.g3.s1': "\"Fotoğraf yükle\"yi seçin ve istediğiniz kadar dosya seçin veya sürükleyin.",
  'simple.help.g3.s2': "Bunları göstermesi gereken ekranları işaretleyin veya daha sonra kullanmak üzere saklamak için hepsinin işaretini kaldırın.",
  'simple.help.g3.s3': "Fotoğrafların her biri 10 saniye süreyle gösterilir; videolar sonuna kadar oynatılır.",
  'simple.help.q1': "Ekran olarak ne kullanabilirim?",
  'simple.help.a1': "Android TV'ler, TV kutuları ve tabletler, Fire TV, LG ve Samsung akıllı TV'ler, Raspberry Pi, Windows ve ChromeOS — veya web tarayıcısı olan herhangi bir cihaz.",
  'simple.help.q2': "Ekranım değişmiyor. Neyi kontrol etmeliyim?",
  'simple.help.a2': "Ekranın ana sayfada \"Oynatılıyor\" ifadesinin göründüğünden emin olun. \"Çevrimdışı\" yazıyorsa cihazın açık ve internete bağlı olduğundan emin olun; yeniden bağlanır bağlanmaz değişikliklerinizi alır.",
  'simple.help.q3': "İnternet kesilirse ne olur?",
  'simple.help.a3': "Ekranlar içeriği yerel olarak tutar ve oynatmaya devam eder. Bağlantı geri geldiğinde yeni değişiklikler gelir.",
  'simple.help.q4': "Hangi dosyaları yükleyebilirim?",
  'simple.help.a4': "Fotoğraf (JPEG, PNG, GIF, WebP), video (en iyi sonuç için MP4) ve ses dosyaları. PDF dosyalarını Gelişmiş görünümdeki medya kütüphanesi sayfasından yükleyebilirsiniz.",
  'simple.help.q5': "Bir ekranı nasıl yeniden adlandırırım veya kaldırırım?",
  'simple.help.a5': "Gelişmiş'e geçin (sağ üst), Ekranlar'ı açın, ekrana tıklayın, ardından sayfanın üst kısmındaki Yeniden adlandır veya kaldır seçeneğini kullanın.",
  'simple.help.q6': "Günün farklı saatlerinde farklı şeyler gösterebilir miyim?",
  'simple.help.a6': "Evet. Gelişmiş görünümdeki yayın takvimi bölümünü kullanın. Basit görünümde, siz değiştirene kadar ekranda aynı içerik gösterilir.",
  'simple.help.trial_q': "Ücretsiz deneme nasıl çalışır?",
  'simple.help.trial_a': "Tüm özelliklerin kilidi açık ve kart gerektirmeden 14 günlük Pro planına sahip olursunuz. Bittiğinde Ücretsiz plana geçersiniz: Hiçbir şey silinmez ve Ücretsiz planın ötesindeki ekranlar siz bir plan seçene kadar duraklatılır.",
  'stats.prompt.title': "ScreenTinker kullanımının yaygınlığını göstermeye yardımcı olur musunuz?",
  'stats.prompt.body': "Çoğu yükleme özel olduğundan, kaç ekranın bulunduğunu söyleyemiyoruz. Paylaşım, rastgele bir kimlik, sürüm ve kaç ekran çalıştırdığınızı gönderir; başka hiçbir şey olmaz. Bunu istediğiniz zaman Ayarlar'dan değiştirebilirsiniz.",
  'stats.prompt.share': "Paylaş",
  'stats.prompt.no': "Hayır teşekkürler",
  'stats.prompt.thanks': "Teşekkür ederiz — kurulum istatistikleri paylaşılıyor",
