  'pos.square_step1': "Developer.squareup.com'a gidin ve Square hesabınızla oturum açın. “Bir uygulama oluştur”u seçin ve ona bir ad verin, ör. Ekranlar.",
  'pos.square_step2': "Uygulamayı açın, üstteki Üretim'e geçin, Kimlik Bilgileri'ni açın ve Üretim erişim belirtecini kopyalayın.",
  'pos.square_step3': "Aşağıya yapıştırın ve Bağlantıyı test et'e basın, ardından mağazanızın konumunu seçin.",
  'pos.square_token_note': "Square bu belirtece hesabınıza tam erişim yetkisi verir. ScreenTinker yalnızca ürün kütüphanenizi ve konumlarınızı okumak için kullanır; belirteci şifreli saklar. Başka hiçbir yere yapıştırmayın.",
