  'pos.secret_note': "Belirteç şifrelenmiş olarak saklanır ve bir daha asla gösterilmez. Kaydedileni korumak için düzenleme yaparken boş bırakın.",
  'pos.shopify_steps_title': "Shopify'a bağlanın",
  'pos.shopify_step1': "Shopify yöneticinizde Ayarlar → Uygulamalar → Uygulama geliştir'i açın ve özel uygulamanızı kullanın. Artık burada uygulama oluşturamayan mağazalar, Shopify Dev Dashboard'da (dev.shopify.com) bir uygulama oluşturur ve bunu mağazaya yükler.",
  'pos.shopify_step2': "Uygulamaya yalnızca read_products iznini verin; başka bir şey değil.",
  'pos.shopify_step3': "Admin API erişim belirtecini (shpat_ ile başlar) veya Dev Dashboard uygulamasının istemci kimliğini ve sırrını yapıştırın ve ardından Bağlantıyı test et'e basın.",
  'pos.store_domain': "Mağaza adresi",
