  'migrate.how.yodeck': "Yodeck'te Hesap ayarları, Gelişmiş Ayarlar, API Belirteçleri'ni açın ve bir belirteç oluşturun (Premium veya Kurumsal plan). Bunu label:token olarak yapıştırın. Yodeck, yüklenen orijinal görselleri ve belgeleri API'si aracılığıyla dağıtmaz: bunlar, zip içe aktarma işlemiyle ekleyebilmeniz için listelenmiştir. Yodeck'in oynatıldığı sürümde videolar gelir.",
  'migrate.how.optisigns': "OptiSigns’ın API’si olsa da dosyaları indirmek için belgelenmiş bir yöntem sunmuyor; oynatma listesi boş gelir. Dosyaları OptiSigns’tan indirip zip ile içe aktarın: her liste için bir klasör veya playlists.csv kullanın.",
  'migrate.how.screencloud': "ScreenCloud Studio'da Hesap ayarları'nı, ardından Geliştirici sekmesini açın ve okuma izinlerine sahip bir belirteç oluşturun. Orada gösterilen bölgeyi seçin (AB veya ABD). ScreenCloud, bireysel kanal öğelerinde zaman kurallarını tutar; bunlar listelenir, içe aktarılmaz.",
