  'ui.workspace_rename_modal.slug_d15387': "Kısa ad",
  'ui.settings.sandbox_disable_warning': "Bileşen HTML kodu şu anda ayrı kaynaklı (null-origin) bir korumalı alanda çalışır. Böylece bileşen kodu oturumunuza, çerezlerinize veya ScreenTinker'ın bu tarayıcıda sakladığı diğer verilere erişemez.\n\nBu korumayı kapatmak allow-same-origin iznini yeniden etkinleştirir. Bileşen HTML kodu, ScreenTinker ile aynı yetkilerle çalışır. Bu kuruluştaki herhangi bir bileşenin betikleri şunları yapabilir:\n\n  - Bileşeni gösteren her ekranın cihaz belirtecini okuyup ScreenTinker API'sinde o ekran adına işlem yapmak\n  - Kendi tarayıcısında bir ekranı açan oturum sahibi kullanıcının oturum belirtecini okumak\n  - Yönetici işlemleri dahil, ScreenTinker API'sini o kullanıcı adına çağırmak\n  - Bu kuruluştaki diğer tüm ekranların içeriklerini okumak ve değiştirmek\n  - Bu verilerin tamamını kullanıcıya bildirmeden istediği sunucuya göndermek\n\nBileşen düzenleyicisindeki önizleme ETKİLENMEZ: oturumunuzun bulunduğu yönetim panelinin içinde çalıştığından bu ayardan bağımsız olarak yalıtılmış kalır. Bu nedenle bir bileşen önizlemede ve gerçek ekranda farklı davranabilir.\n\nBileşenlerin çalışması için allow-scripts izni de gerektiğinden, aynı kaynağa erişim verildiğinde bir bileşen kendi korumalı alanını tamamen kaldırabilir. Bu noktadan sonra kısmi koruma da kalmaz.\n\nBu seçeneği yalnızca kuruluştaki her bileşenin kodunu kendiniz yazdıysanız veya kaynağına yönetici parolanızı verecek kadar güveniyorsanız etkinleştirin. Ele geçirilmiş tek bir üçüncü taraf yerleştirme kodu, CDN veya reklam etiketi yeterlidir.\n\nBu ayar kuruluştaki TÜM bileşenlere uygulanır; ekran bazında sınırlandırılamaz.",
  'ui.settings.sandbox_confirmation_phrase': "Bir güvenlik açığına izin verdiğimi anlıyorum",
