  'ui.storage.choice_help': "Yeni yüklemeler, varsa çalışma alanının depolama tercihini; yoksa kuruluşun tercihini, o da yoksa sunucu varsayılanını kullanır. Tercih değişikliği yalnızca yeni yüklemeleri etkiler. Mevcut dosyaları taşımak için <em>Medyayı buraya taşı</em> işlemini kullanın. Taşıma sırasında ekranlar yanıt veren mevcut kopyalardan oynatmaya devam eder.",
  'ui.storage.copy_readable': "Ekranlar hâlâ mevcut kopyaları kullanır. <em>Geçiş yap</em> işlemi yeni kopyaları birincil yapar; eski kopyalar siz kaldırana kadar okunabilir kalır.",
  'ui.storage.copy_preferred': "Okumada yeni kopyalara öncelik verilir. Eski kopyalar siz kaldırana kadar, yeni kopyalarda sorun olursa kullanılmaya devam eder.",
  'ui.storage.env_default': "<code>STORAGE_PROVIDER</code> ayarlı olduğundan sunucu varsayılanını belirler. Sunucu varsayılanını buradan yönetmek için bu ortam ayarını kaldırıp yeniden başlatın.",
