  'ui.help.what_devices_are_supported_c6e59c': "Hangi cihazlar destekleniyor?",
  'ui.help.android_tv_tablets_apk_raspberry_pi_windows_chromeos_lg_db7064': "Android TV/tabletler (APK), Raspberry Pi, Windows, ChromeOS, LG webOS, Samsung Tizen, Fire TV ve web tarayıcısı olan herhangi bir cihaz.",
  'ui.help.how_does_the_free_trial_work_4a0f2c': "Ücretsiz deneme nasıl çalışır?",
  'ui.help.new_accounts_on_the_hosted_service_get_a_14_day_trial_o_9b301f': "Barındırılan hizmetteki yeni hesaplar, tüm özelliklerin kilidinin açık olduğu ve kart gerekmediği Pro planının 14 günlük deneme süresine sahip olur. Bittiğinde Ücretsiz plana geçersiniz: Hiçbir şey silinmez ve Ücretsiz planın limitinin ötesindeki ekranlar siz bir plan seçene kadar duraklatılır. Abonelik, her plan için kesin sınırları gösterir.",
  'ui.help.can_i_use_portrait_mode_displays_b36420': "Portre modundaki ekranları kullanabilir miyim?",
  'ui.help.yes_set_the_orientation_to_portrait_in_the_device_s_inf_4a6ff1': "Evet. Cihazın Bilgi sekmesinde yönü “Dikey” olarak ayarlayın. İçerik buna göre döndürülür.",
  'ui.help.what_happens_when_a_device_goes_offline_8f06b8': "Bir cihaz çevrimdışı olduğunda ne olur?",
  'ui.help.devices_cache_content_locally_so_they_continue_playing__5c3688': "Cihazlar içeriği yerel olarak önbelleğe alır, böylece internet olmasa bile oynatma listelerini oynatmaya devam ederler. Çevrimdışı kaldıktan 5 dakika sonra bir e-posta uyarısı alacaksınız.",
  'ui.help.can_i_self_host_screentinker_af0c7c': "ScreenTinker'ı kendim barındırabilir miyim?",
  'ui.help.how_do_i_update_the_android_app_f839dc': "Android uygulamasını nasıl güncellerim?",
  'ui.help.the_app_checks_for_updates_automatically_every_30_minut_6a3bda': "Uygulama, güncellemeleri her 30 dakikada bir otomatik olarak kontrol eder. Ayrıca yönetim panelindeki cihazın Bilgi sekmesinden de güncellemeyi zorunlu kılabilirsiniz.",
  'ui.help.what_video_formats_are_supported_c0dfbd': "Hangi video formatları destekleniyor?",
  'ui.help.mp4_h_264_webm_avi_mkv_mov_for_best_compatibility_use_m_86885a': "MP4 (H.264), WebM, AVI, MKV, MOV. En iyi uyumluluk için H.264 kodlamalı MP4 kullanın.",
  'ui.help.can_i_white_label_the_dashboard_961541': "Paneli kendi markamla özelleştirebilir miyim?",
  'ui.help.how_do_i_export_proof_of_play_reports_c1f02f': "Oynatım kanıtı raporlarını nasıl dışa aktarırım?",
  'ui.help.go_to_reports_set_your_date_range_and_filters_then_clic_7a4da1': "Raporlar bölümünde tarih aralığını ve filtreleri ayarlayıp “CSV olarak dışa aktar”a tıklayın.",
  'ui.help.what_is_a_video_wall_b5c9c3': "Video duvarı nedir?",
  'ui.help.a_video_wall_combines_multiple_displays_into_one_large__619b1b': "Bir video duvarı birden fazla ekranı tek bir büyük ekranda birleştirir. Örneğin, 2x2'lik bir ızgarada büyük bir görüntü/video gösteren dört TV.",
  'ui.help.how_do_i_build_a_wall_from_portrait_sideways_mounted_pa_8ab998': "Dikey (yana monte edilmiş) panellerden nasıl video duvarı oluştururum?",
  'ui.help.arrange_the_tiles_on_the_wall_canvas_exactly_as_the_pan_07b12f': "Panelleri duvar tuvalinde fiziksel montajlarıyla aynı biçimde yerleştirin; yan yana duran paneller tuvalde de yan yana kalmalıdır. Her paneli seçip “Panelin montaj yönü”nü dönüşüne göre ayarlayın. Oynatıcı içeriği kendisi döndürür; videonun önceden döndürülmüş bir kopyası gerekmez. Ekran bir video duvarındayken bu ayar ekranın kendi Yön ayarının yerine geçer.",
