  'ui.ai_hosted_picker.generate_with_value0_this_spends_value1_credits_value2_you_have_v_fd7789': "{value0} ile oluşturulsun mu?\n\nBu işlem {value1} kredi ({value2}) harcar. Bakiyeniz: {value3}. Oluşturma başarısız olursa ücret alınmaz.",
