  'ui.storage_settings.delete_the_storage_profile_value0_files_are_not_touched_a_profile_515f5c': "\"{value0}\" depolama profili silinsin mi? Dosyalara dokunulmaz; hâlâ dosyaları barındıran bir profil silinemez.",
  'ui.storage_settings.copy_every_file_in_value0_to_value1_nothing_is_switched_or_remove_4b70af': "{value0} kapsamındaki tüm dosyalar “{value1}” profiline kopyalansın mı? Siz karar verene kadar geçiş yapılmaz veya dosya kaldırılmaz. Ekranlar işlem boyunca oynatmaya devam eder.",
  'ui.storage_settings.removed_value0_old_cop_value1_d26562': "{value0} eski kopya{value1} kaldırıldı",
