  'ui.storage_settings.delete_the_instance_storage_profile_value0_organizations_that_fol_9f6848': "“{value0}” sunucu depolama profili silinsin mi? Sunucu varsayılanını kullanan kuruluşların yeni yüklemeleri yerel diske kaydedilir. Hâlâ dosya içeren bir profil silinemez.",
