  'builtin.templates.uptime_3036.name': "UPTIME 3036",
  'builtin.templates.uptime_3036.description': "3036 yılının en zorlu nöbetini konu alan, birinci şahıs bakış açılı özgün bir aksiyon oyunu: tüm sunucular çökmüş ve veri merkezi böceklerle dolu. Kimse oynamıyorsa otomatik demo oynar. Kontrolü devralmak için tıklayın veya bir tuşa basın; etkileşim kesilince demo yeniden devreye girer.",
