  'builtin.templates.weather_forecast.params.weather.label': "Hava durumu veri kaynağı",
  'builtin.templates.weather_forecast.params.weather.help': "Hava durumu türünde bir veri kaynağı (Veri kaynakları → Yeni → Hava durumu). Konum, birim ve dil orada ayarlanır.",
  'builtin.templates.weather_forecast.params.location.label': "Konum adı",
